SELECT strftime(OrderDate,'%Y-%m') AS Month,COUNT(*) FILTER(WHERE PickingCompletedWhen IS NOT NULL) Completed,COUNT(*) FILTER(WHERE PickingCompletedWhen IS NULL) Incomplete,COUNT(*) FILTER(WHERE PickingCompletedWhen<CAST(OrderDate AS TIMESTAMP)) Invalid,median(epoch(PickingCompletedWhen-CAST(OrderDate AS TIMESTAMP))/3600) MedianDateBasedHours FROM raw.Sales_Orders GROUP BY 1 ORDER BY 1